// generate_image (Q423-Q429): an image generated by the maker's account,
// added to media/ as WebP with its alternative text and, instead of credits,
// how it was made: the model, the prompt, the date and the images it started
// from. The original of a retouched image stays.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { Generation } from "@upstart/runtime";
import { addImage, mediaKind } from "../media/library";
import { type GeneratedImage, type GenerateRequest, MAX_REFERENCES, type Reference } from "./generate";

export type GenerateInput = {
  prompt: string;
  aspect: GenerateRequest["aspect"];
  name: string;
  alt: string;
  references?: string[];
};

/** Reads the project's images given as references, each brought to 1536 px at most. */
export async function readReferences(root: string, paths: string[]): Promise<Reference[]> {
  if (paths.length > MAX_REFERENCES) throw new Error(`At most ${MAX_REFERENCES} references.`);
  const sharp = (await import("sharp")).default;
  const out: Reference[] = [];
  for (const given of paths) {
    const path = given.replace(/^\//, "");
    if (!/^media\/[^/]+$/.test(path) || mediaKind(path) !== "image" || path.endsWith(".svg"))
      throw new Error(`${given} is not an image of the project's media/: give its address, such as /media/cafe.jpg.`);
    const abs = join(root, path);
    if (!existsSync(abs)) throw new Error(`${given} does not exist.`);
    const image = sharp(readFileSync(abs), { animated: false })
      .rotate()
      .resize(1536, 1536, { fit: "inside", withoutEnlargement: true });
    const meta = await sharp(readFileSync(abs)).metadata();
    out.push(
      meta.hasAlpha
        ? { data: await image.png().toBuffer(), mimeType: "image/png" }
        : { data: await image.jpeg({ quality: 88 }).toBuffer(), mimeType: "image/jpeg" },
    );
  }
  return out;
}

/**
 * Generates an image with `generate` and adds it to media/, answering the
 * agent with its address and how to use it.
 */
export async function generateIntoMedia(
  root: string,
  model: string,
  input: GenerateInput,
  generate: (request: GenerateRequest) => Promise<GeneratedImage>,
  now = () => new Date(),
): Promise<string> {
  const prompt = input.prompt?.trim();
  if (!prompt) return "Say what the image shows in `prompt`.";
  const references = (input.references ?? []).map((r) => `/${r.replace(/^\//, "")}`);
  let read: Reference[];
  try {
    read = await readReferences(root, references);
  } catch (error) {
    return (error as Error).message;
  }
  let image: GeneratedImage;
  try {
    image = await generate({ prompt, aspect: input.aspect, references: read });
  } catch (error) {
    return `The image was not generated: ${(error as Error).message}`;
  }
  const sharp = (await import("sharp")).default;
  const webp = await sharp(image.data).webp({ quality: 85 }).toBuffer();
  const generated: Generation = {
    model,
    prompt,
    date: now().toISOString(),
    ...(references.length ? { references } : {}),
  };
  const added = await addImage(root, input.name || "generated", webp, { alt: input.alt ?? "", generated });
  return `Generated and added as /${added.path}${added.width ? ` (${added.width}×${added.height})` : ""}. Write <img src="/${added.path}" …> in a page, part or record without an alt attribute: Upstart takes its alternative text from ${added.path.replace(/\.[^.]+$/, ".json")}, where the maker can change it. Look at the page to see it in place.`;
}
